1	import test from 'node:test';
2	import assert from 'node:assert/strict';
3	import { createInvoice, issueInvoice } from '../src/invoices.js';
4	import { renderInvoiceText } from '../src/render.js';
5	
6	test('renderInvoiceText renders draft invoice with correct format', () => {
7	  const r = createInvoice({
8	    customerId: 'C-001',
9	    issueDate: '2024-01-15',
10	    lines: [
11	      { sku: 'DEV-HOUR', qty: 10, discountPercent: 0 },
12	      { sku: 'LOGO-PACK', qty: 1, discountPercent: 0 },
13	    ],
14	  });
15	
16	  assert.equal(r.ok, true);
17	  const text = renderInvoiceText(r.value);
18	
19	  const lines = text.split('\n');
20	  assert.equal(lines[0], 'DRAFT');
21	  assert.equal(lines[1], 'Northwind Studio');
22	  assert(lines[2].includes('10x Development (hour)'));
23	  assert(lines[2].includes('€95.00'));
24	  assert(lines[2].includes('€950.00'));
25	  assert(lines[3].includes('1x Logo package'));
26	  assert(lines[3].includes('€1,200.00'));
27	  // Should have Subtotal, VAT, and Total lines
28	  assert(text.includes('Subtotal:'));
29	  assert(text.includes('VAT:'));
30	  assert(text.includes('Total:'));
31	});
32	
33	test('renderInvoiceText renders issued invoice with number', () => {
34	  const r1 = createInvoice({
35	    customerId: 'C-002',
36	    issueDate: '2024-02-20',
37	    lines: [{ sku: 'COPY-HOUR', qty: 5 }],
38	  });
39	
40	  assert.equal(r1.ok, true);
41	  const r2 = issueInvoice(r1.value, []);
42	  assert.equal(r2.ok, true);
43	
44	  const text = renderInvoiceText(r2.value);
45	  const lines = text.split('\n');
46	
47	  assert.equal(lines[0], 'INV-2024-0001');
48	  assert.equal(lines[1], 'Blue Fern Bakery');
49	  assert(lines[2].includes('5x Copywriting (hour)'));
50	  assert(lines[2].includes('€60.00'));
51	});
52	
53	test('renderInvoiceText calculates line totals correctly with VAT', () => {
54	  const r = createInvoice({
55	    customerId: 'C-003',
56	    issueDate: '2024-03-10',
57	    lines: [{ sku: 'PRINT-A4', qty: 100, discountPercent: 0 }],
58	  });
59	
60	  assert.equal(r.ok, true);
61	  const text = renderInvoiceText(r.value);
62	
63	  // 3700 cents subtotal, VAT 9% = 333 cents
64	  assert(text.includes('100x Printed flyer A4 (each)'));
65	  assert(text.includes('€0.37'));
66	  assert(text.includes('€37.00'));
67	  assert(text.includes('VAT: €3.33'));
68	  assert(text.includes('Total: €40.33'));
69	});
70	
71	test('renderInvoiceText formats euros correctly with thousands separator', () => {
72	  const r = createInvoice({
73	    customerId: 'C-001',
74	    issueDate: '2024-01-15',
75	    lines: [{ sku: 'BRAND-BOOK', qty: 1, discountPercent: 0 }],
76	  });
77	
78	  assert.equal(r.ok, true);
79	  const text = renderInvoiceText(r.value);
80	
81	  // 245000 cents subtotal, VAT 21% = 51450 cents = €514.50
