import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, issueInvoice } from '../src/invoices.js';
import { renderInvoiceText } from '../src/render.js';

test('renderInvoiceText renders draft invoice with correct format', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 10, discountPercent: 0 },
      { sku: 'LOGO-PACK', qty: 1, discountPercent: 0 },
    ],
  });

  assert.equal(r.ok, true);
  const text = renderInvoiceText(r.value);

  const lines = text.split('\n');
  assert.equal(lines[0], 'DRAFT');
  assert.equal(lines[1], 'Northwind Studio');
  assert(lines[2].includes('10x Development (hour)'));
  assert(lines[2].includes('€95.00'));
  assert(lines[2].includes('€950.00'));
  assert(lines[3].includes('1x Logo package'));
  assert(lines[3].includes('€1,200.00'));
  // Should have Subtotal, VAT, and Total lines
  assert(text.includes('Subtotal:'));
  assert(text.includes('VAT:'));
  assert(text.includes('Total:'));
});

test('renderInvoiceText renders issued invoice with number', () => {
  const r1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-02-20',
    lines: [{ sku: 'COPY-HOUR', qty: 5 }],
  });

  assert.equal(r1.ok, true);
  const r2 = issueInvoice(r1.value, []);
  assert.equal(r2.ok, true);

  const text = renderInvoiceText(r2.value);
  const lines = text.split('\n');

  assert.equal(lines[0], 'INV-2024-0001');
  assert.equal(lines[1], 'Blue Fern Bakery');
  assert(lines[2].includes('5x Copywriting (hour)'));
  assert(lines[2].includes('€60.00'));
});

test('renderInvoiceText calculates line totals correctly with VAT', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2024-03-10',
    lines: [{ sku: 'PRINT-A4', qty: 100, discountPercent: 0 }],
  });

  assert.equal(r.ok, true);
  const text = renderInvoiceText(r.value);

  // 3700 cents subtotal, VAT 9% = 333 cents
  assert(text.includes('100x Printed flyer A4 (each)'));
  assert(text.includes('€0.37'));
  assert(text.includes('€37.00'));
  assert(text.includes('VAT: €3.33'));
  assert(text.includes('Total: €40.33'));
});

test('renderInvoiceText formats euros correctly with thousands separator', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'BRAND-BOOK', qty: 1, discountPercent: 0 }],
  });

  assert.equal(r.ok, true);
  const text = renderInvoiceText(r.value);

  // 245000 cents subtotal, VAT 21% = 51450 cents = €514.50
  assert(text.includes('€2,450.00'));
  assert(text.includes('€514.50'));
  assert(text.includes('Total: €2,964.50'));
});

test('renderInvoiceText includes customer name', () => {
  const r = createInvoice({
    customerId: 'C-005',
    issueDate: '2024-01-15',
    lines: [{ sku: 'HOST-MONTH', qty: 1 }],
  });

  assert.equal(r.ok, true);
  const text = renderInvoiceText(r.value);

  assert(text.includes('Orchard Health'));
});

test('renderInvoiceText handles multiple lines', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 8, discountPercent: 0 },
      { sku: 'COPY-HOUR', qty: 4, discountPercent: 0 },
      { sku: 'SUPPORT-HOUR', qty: 2, discountPercent: 0 },
    ],
  });

  assert.equal(r.ok, true);
  const text = renderInvoiceText(r.value);

  const lines = text.split('\n');
  // DRAFT, Customer, 3 items, Subtotal, VAT, Total
  assert.equal(lines.length, 8);
  assert(lines[2].includes('8x Development'));
  assert(lines[3].includes('4x Copywriting'));
  assert(lines[4].includes('2x Support'));
});

test('renderInvoiceText has correct total for multi-line invoice with VAT', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 10, discountPercent: 0 }, // subtotal €950.00, VAT €199.50
      { sku: 'LOGO-PACK', qty: 1, discountPercent: 0 }, // subtotal €1,200.00, VAT €252.00
    ],
  });

  assert.equal(r.ok, true);
  const text = renderInvoiceText(r.value);

  assert(text.includes('Total: €2,601.50')); // 2150 + 451.50 VAT
});

test('renderInvoiceText preserves item order', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 1 },
      { sku: 'COPY-HOUR', qty: 1 },
      { sku: 'SUPPORT-HOUR', qty: 1 },
    ],
  });

  assert.equal(r.ok, true);
  const text = renderInvoiceText(r.value);
  const lines = text.split('\n');

  assert(lines[2].includes('Development'));
  assert(lines[3].includes('Copywriting'));
  assert(lines[4].includes('Support'));
});

test('renderInvoiceText formats with 2 decimal places', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'PHOTO-LIC', qty: 1, discountPercent: 0 }], // €9.96, VAT 21% = €2.09
  });

  assert.equal(r.ok, true);
  const text = renderInvoiceText(r.value);

  assert(text.includes('€9.96'));
  assert(text.includes('Total: €12.05')); // 9.96 + 2.09
});

test('renderInvoiceText does not mutate invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(r.ok, true);
  const originalInvoice = JSON.parse(JSON.stringify(r.value));

  renderInvoiceText(r.value);

  assert.deepEqual(r.value, originalInvoice);
});

test('renderInvoiceText shows discount on line', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 10 }],
  });

  assert.equal(r.ok, true);
  const text = renderInvoiceText(r.value);

  assert(text.includes('10% off'));
  assert(text.includes('-€95.00'));
});

test('renderInvoiceText shows subtotal, discount, and VAT when there is a discount', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 10 }],
  });

  assert.equal(r.ok, true);
  const text = renderInvoiceText(r.value);
  const lines = text.split('\n');

  // subtotal 95000, discount 9500, amount 85500, VAT at 21% = 17955
  assert(lines.some((line) => line.includes('Subtotal: €950.00')));
  assert(lines.some((line) => line.includes('Discount: -€95.00')));
  assert(lines.some((line) => line.includes('VAT: €179.55')));
  assert(lines.some((line) => line.includes('Total: €1,034.55')));
});

test('renderInvoiceText shows subtotal and VAT when VAT present but no discount', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 0 }],
  });

  assert.equal(r.ok, true);
  const text = renderInvoiceText(r.value);

  assert(text.includes('Subtotal:'));
  assert(!text.includes('Discount:'));
  assert(text.includes('VAT:'));
  assert(text.includes('Total: €1,149.50')); // 950 + 199.50 VAT
});

test('renderInvoiceText with multiple lines with different discounts', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 10, discountPercent: 10 }, // 95000 - 9500 = 85500, VAT 17955
      { sku: 'LOGO-PACK', qty: 1, discountPercent: 20 }, // 120000 - 24000 = 96000, VAT 20160
    ],
  });

  assert.equal(r.ok, true);
  const text = renderInvoiceText(r.value);

  assert(text.includes('10% off'));
  assert(text.includes('20% off'));
  assert(text.includes('Subtotal: €2,150.00'));
  assert(text.includes('Discount: -€335.00'));
  assert(text.includes('VAT: €381.15')); // 17955 + 20160 = 38115 cents = €381.15
  assert(text.includes('Total: €2,196.15')); // 2150 - 335 + 381.15
});

test('renderInvoiceText handles decimal discount percentages', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 12.5 }],
  });

  assert.equal(r.ok, true);
  const text = renderInvoiceText(r.value);

  assert(text.includes('12.5% off'));
});

test('renderInvoiceText shows VAT line when VAT present', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 0 }],
  });

  assert.equal(r.ok, true);
  const text = renderInvoiceText(r.value);

  assert(text.includes('VAT:'));
  assert(text.includes('€199.50'));
});

test('renderInvoiceText shows subtotal, VAT, and total when VAT present', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 0 }],
  });

  assert.equal(r.ok, true);
  const text = renderInvoiceText(r.value);
  const lines = text.split('\n');

  assert(lines.some((line) => line.includes('Subtotal:')));
  assert(lines.some((line) => line.includes('VAT:')));
  assert(lines.some((line) => line.startsWith('Total:')));
});

test('renderInvoiceText shows VAT with discount', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 10 }],
  });

  assert.equal(r.ok, true);
  const text = renderInvoiceText(r.value);
  const lines = text.split('\n');

  assert(lines.some((line) => line.includes('Subtotal: €950.00')));
  assert(lines.some((line) => line.includes('Discount: -€95.00')));
  assert(lines.some((line) => line.includes('VAT: €179.55')));
  assert(lines.some((line) => line.includes('Total: €1,034.55')));
});

test('renderInvoiceText does not show VAT line for 0% VAT', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'WORKSHOP-DAY', qty: 1, discountPercent: 0 }],
  });

  assert.equal(r.ok, true);
  const text = renderInvoiceText(r.value);

  assert(!text.includes('VAT:'));
  assert(!text.includes('Subtotal:'));
  assert(text.includes('Total: €600.00'));
});

test('renderInvoiceText with multiple VAT rates', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 10, discountPercent: 0 }, // 21% VAT
      { sku: 'PRINT-A4', qty: 100, discountPercent: 0 }, // 9% VAT
    ],
  });

  assert.equal(r.ok, true);
  const text = renderInvoiceText(r.value);

  assert(text.includes('Subtotal: €987.00'));
