import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, issueInvoice, applyVoucher } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';
import { renderInvoiceText } from '../src/render.js';

test('renderInvoiceText renders draft invoice with correct format', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 10, discountPercent: 0 },
      { sku: 'LOGO-PACK', qty: 1, discountPercent: 0 },
    ],
  });

  assert.equal(r.ok, true);
  const text = renderInvoiceText(r.value);

  const lines = text.split('\n');
  assert.equal(lines[0], 'DRAFT');
  assert.equal(lines[1], 'Northwind Studio');
  assert(lines[2].includes('10x Development (hour)'));
  assert(lines[2].includes('€95.00'));
  assert(lines[2].includes('€950.00'));
  assert(lines[3].includes('1x Logo package'));
  assert(lines[3].includes('€1,200.00'));
  // Should have Subtotal, VAT, and Total lines
  assert(text.includes('Subtotal:'));
  assert(text.includes('VAT:'));
  assert(text.includes('Total:'));
});

test('renderInvoiceText renders issued invoice with number', () => {
  const r1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-02-20',
    lines: [{ sku: 'COPY-HOUR', qty: 5 }],
  });

  assert.equal(r1.ok, true);
  const r2 = issueInvoice(r1.value, []);
  assert.equal(r2.ok, true);

  const text = renderInvoiceText(r2.value);
  const lines = text.split('\n');

  assert.equal(lines[0], 'INV-2024-0001');
  assert.equal(lines[1], 'Blue Fern Bakery');
  assert(lines[2].includes('5x Copywriting (hour)'));
  assert(lines[2].includes('€60.00'));
});

test('renderInvoiceText calculates line totals correctly with VAT', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2024-03-10',
    lines: [{ sku: 'PRINT-A4', qty: 100, discountPercent: 0 }],
  });

  assert.equal(r.ok, true);
  const text = renderInvoiceText(r.value);

  // 3700 cents subtotal, VAT 9% = 333 cents
  assert(text.includes('100x Printed flyer A4 (each)'));
  assert(text.includes('€0.37'));
  assert(text.includes('€37.00'));
  assert(text.includes('VAT: €3.33'));
  assert(text.includes('Total: €40.33'));
});

test('renderInvoiceText formats euros correctly with thousands separator', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'BRAND-BOOK', qty: 1, discountPercent: 0 }],
  });

  assert.equal(r.ok, true);
  const text = renderInvoiceText(r.value);

  // 245000 cents subtotal, VAT 21% = 51450 cents = €514.50
  assert(text.includes('€2,450.00'));
  assert(text.includes('€514.50'));
  assert(text.includes('Total: €2,964.50'));
});

test('renderInvoiceText includes customer name', () => {
  const r = createInvoice({
    customerId: 'C-005',
    issueDate: '2024-01-15',
    lines: [{ sku: 'HOST-MONTH', qty: 1 }],
  });

  assert.equal(r.ok, true);
  const text = renderInvoiceText(r.value);

  assert(text.includes('Orchard Health'));
});

test('renderInvoiceText handles multiple lines', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 8, discountPercent: 0 },
      { sku: 'COPY-HOUR', qty: 4, discountPercent: 0 },
      { sku: 'SUPPORT-HOUR', qty: 2, discountPercent: 0 },
    ],
  });

  assert.equal(r.ok, true);
  const text = renderInvoiceText(r.value);

  const lines = text.split('\n');
  // DRAFT, Customer, 3 items, Subtotal, VAT, Total
  assert.equal(lines.length, 8);
  assert(lines[2].includes('8x Development'));
  assert(lines[3].includes('4x Copywriting'));
  assert(lines[4].includes('2x Support'));
});

test('renderInvoiceText has correct total for multi-line invoice with VAT', () => {
  const r = createInvoice({
