import { getCustomer } from './customers.js';
import { invoiceTotals, lineTotal, lineDiscount } from './invoices.js';
import { formatEuros } from './money.js';

/**
 * Render an invoice as plain text for display to customers.
 * @param {{ customerId: string, number?: string, lines: Array<{ qty: number, name: string, unitPrice: number, discountPercent?: number, vatRate: number }>, voucher?: { code: string, amount: number }, dueDate?: string, payments?: Array<{ amount: number, date: string }> }} invoice
 * @returns {string}
 */
export function renderInvoiceText(invoice) {
  const customerResult = getCustomer(invoice.customerId);
  const customerName = customerResult.ok ? customerResult.value.name : 'Unknown Customer';

  const numberLine = invoice.number ?? 'DRAFT';
  const lines = [numberLine, customerName];

  for (const line of invoice.lines) {
    const total = lineTotal(line);
    const discount = lineDiscount(line);
    const discountText = discount > 0 ? ` (${line.discountPercent}% off: -${formatEuros(discount)})` : '';
    const lineText = `  ${line.qty}x ${line.name} @ ${formatEuros(line.unitPrice)} = ${formatEuros(total)}${discountText}`;
    lines.push(lineText);
  }

  const totals = invoiceTotals(invoice);
  if (totals.discount > 0 || totals.vat > 0) {
    lines.push(`Subtotal: ${formatEuros(totals.subtotal)}`);
    if (totals.discount > 0) {
      lines.push(`Discount: -${formatEuros(totals.discount)}`);
    }
    if (totals.vat > 0) {
      lines.push(`VAT: ${formatEuros(totals.vat)}`);
    }
  }

  if (invoice.voucher) {
    lines.push(`Voucher: -${formatEuros(invoice.voucher.amount)}`);
  }

  lines.push(`Total: ${formatEuros(totals.total)}`);

  if (invoice.dueDate) {
    lines.push(`Due: ${invoice.dueDate}`);
  }

  if (invoice.payments && invoice.payments.length > 0) {
    const paid = invoice.payments.reduce((sum, p) => sum + p.amount, 0);
    lines.push(`Paid: ${formatEuros(paid)}`);
  }

  return lines.join('\n');
}
